-- State transitions declared for ItemGroup (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION catalog.item_groups_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: item_groups.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS item_groups_status_transition_check ON catalog.item_groups;
CREATE TRIGGER item_groups_status_transition_check
    BEFORE UPDATE OF "status" ON catalog.item_groups
    FOR EACH ROW EXECUTE FUNCTION catalog.item_groups_status_transition_check();
